const operation={optimizer:{title:'AI Resource Optimizer',intro:'Find a teaching-ready room from capacity, equipment, maintenance and timetable constraints.',icon:'✦'},rooms:{title:'Rooms & resources',intro:'Search, filter and inspect every CSE space with a consistent room-card layout.',icon:'⌂'},maintenance:{title:'Maintenance desk',intro:'Prioritise open issues, update repair state and keep verification visible to the team.',icon:'⚑'},timetable:{title:'Clash-free timetable',intro:'Create a timetable entry while checking room, section and lecturer conflicts.',icon:'◫'},progress:{title:'Syllabus progress',intro:'Record weekly coverage and keep teaching progress connected to the timetable.',icon:'📈'}};
const localOps=JSON.parse(localStorage.getItem('campusTwinOpsV2')||'{}');
function saveLocalOp(key,value){localOps[key]=value;localStorage.setItem('campusTwinOpsV2',JSON.stringify(localOps));}
const escOp=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let roomDirectory=[],activeRoomCategory='All';
const statusClass=s=>String(s||'').toLowerCase()==='attention'?'watch':String(s||'').toLowerCase()==='unavailable'?'critical':String(s||'').toLowerCase()==='empty'?'empty':'stable';
function normalizeRoomRecord(r){const row={...(r||{})};row.internet=row.internet||row.network||'';row.network=row.internet;row.other_resources=row.other_resources||'';row.resources=Array.isArray(row.resources)?row.resources:[];return row;}
function roomCard(input){const r=normalizeRoomRecord(input);const resourceText=r.resources.length?r.resources.map(x=>`${x.name} (${x.available_count}/${x.total_count})`).join(', '):r.other_resources||'—';return `<article class="room-card ${statusClass(r.status)}"><div class="room-card-head"><div><span class="room-code">${escOp(r.room_number)}</span><h3>${escOp(r.room_name)}</h3><small>${escOp(r.category)} · ${escOp(r.floor||'Floor not set')}</small></div><b class="room-status">${escOp(r.status)}</b></div><div class="room-grid"><div><span>Seats</span><b>${escOp(r.capacity)}</b></div><div><span>Occupied</span><b>${escOp(r.occupied_seats)}</b></div><div><span>Benches</span><b>${escOp(r.benches)}</b></div><div><span>Projector</span><b>${escOp(r.projector)}</b></div><div><span>Board</span><b>${escOp(r.board)}</b></div><div><span>Network</span><b>${escOp(r.internet)}</b></div></div><div class="room-resources">Resources: ${escOp(resourceText)}</div><div class="room-card-actions"><button class="room-open" data-room="${escOp(r.room_number)}">View details →</button><button class="room-edit" data-edit-room="${escOp(r.room_number)}">Edit</button></div></article>`;}

async function loadLiveRooms(){
 try{
  const data=await tryApi('/api/rooms');
  roomDirectory=Array.isArray(data)?data.map(normalizeRoomRecord):[];
  renderRooms();
  return roomDirectory;
 }catch(err){
  roomDirectory=[]; renderRooms();
  toast(err.message||'Live room data is unavailable.');
  return [];
 }
}
function renderRooms(){const host=$('#c-room-grid');if(!host)return;const q=($('#c-room-search')?.value||'').trim().toLowerCase(),cat=activeRoomCategory;const filtered=roomDirectory.filter(r=>(!q||`${r.room_number} ${r.room_name}`.toLowerCase().includes(q))&&(cat==='All'||r.category===cat));host.innerHTML=filtered.map(roomCard).join('')||'<div class="rooms-empty">No spaces match the current filters.</div>';bindRoomButtons();const count={available:0,attention:0,unavailable:0,empty:0};roomDirectory.forEach(r=>count[String(r.status||'').toLowerCase()]++);['available','attention','unavailable','empty'].forEach(k=>{const n=$('#c-room-'+k);if(n)n.textContent=count[k]||0});const seats=roomDirectory.reduce((a,r)=>a+Number(r.capacity||0),0);const occupied=roomDirectory.reduce((a,r)=>a+Number(r.occupied_seats||0),0);if($('#c-room-seats'))$('#c-room-seats').textContent=seats;if($('#c-room-total'))$('#c-room-total').textContent=roomDirectory.length;}
function bindRoomButtons(){$$('[data-room]').forEach(x=>x.onclick=()=>{const key=x.dataset.room;const r=roomDirectory.find(v=>v.room_number===key)||roomDirectory.find(v=>v.room_name===key);const detail=$('#c-room-detail');if(detail&&r){detail.innerHTML=`<b>${escOp(r.room_number)} · ${escOp(r.room_name)}</b><p>${escOp(r.category)} · capacity ${escOp(r.capacity)} · occupied ${escOp(r.occupied_seats)} · status ${escOp(r.status)}.</p><p>Equipment: ${escOp(r.projector)}, ${escOp(r.board)}, ${escOp(r.internet||r.network)}. Recommended next action: ${r.status==='Attention'?'Open a maintenance check.':r.status==='Unavailable'?'Keep out of booking until cleared.':'Use this room for the next compatible allocation.'}</p>`;detail.scrollIntoView({behavior:'smooth',block:'center'});}else toast(`${key} selected.`);});}
async function tryApi(url,opts={}){const requestOpts={cache:'no-store',headers:{'Content-Type':'application/json',...(opts.headers||{})},...opts};const r=await fetch(url,requestOpts);const data=await r.json().catch(()=>({}));if(!r.ok)throw Error(data.error||'Server update failed');return data;}
function renderLocalRooms(){const rooms=localOps.rooms||[];return rooms.length?`<table class="operation-table"><thead><tr><th>Room</th><th>Type</th><th>Capacity</th><th>Status</th></tr></thead><tbody>${rooms.map(r=>`<tr><td>${escOp(r.name)}</td><td>${escOp(r.type)}</td><td>${escOp(r.capacity)}</td><td>${escOp(r.status)}</td></tr>`).join('')}</tbody></table>`:'No local resource records yet.';}
function issueCard(i){const room=i.rooms?.room_number||'Campus';const floor=i.rooms?.floor?' · '+i.rooms.floor:'';const status=i.status||'Open';const verification=i.faculty_verification||'Pending';const assigned=i.assigned_to?'Assigned':'Unassigned';return '<article class="issue-card '+String(i.priority||'Medium').toLowerCase()+'" data-issue-id="'+escOp(i.id)+'"><div class="issue-main"><div class="issue-top"><span class="priority-pill">'+escOp(i.priority||'Medium')+'</span><span class="issue-status">'+escOp(status)+'</span></div><h3>'+escOp(i.title||'Reported issue')+'</h3><p>'+escOp(i.description||'No description supplied.')+'</p><div class="issue-meta"><span>'+escOp(i.category||'General')+'</span><span>'+escOp(room+floor)+'</span><span>'+escOp(assigned)+'</span><span>Faculty: '+escOp(verification)+'</span></div></div><div class="issue-room"><b>'+escOp(room)+'</b><small>'+escOp(i.rooms?.room_name||'Campus space')+'</small></div></article>';}
function uniqueIssues(rows){const seen=new Set();return (Array.isArray(rows)?rows:[]).filter(i=>{if(!i?.id||seen.has(String(i.id)))return false;seen.add(String(i.id));return true;});}
function maintenanceSummary(rows){const counts={total:rows.length,open:0,inProgress:0,resolved:0,verified:0,critical:0,unassigned:0};rows.forEach(i=>{const s=i.status||'Open';if(s==='Open')counts.open++;if(s==='In Progress')counts.inProgress++;if(s==='Resolved')counts.resolved++;if(s==='Verified')counts.verified++;if(i.priority==='Critical')counts.critical++;if(!i.assigned_to)counts.unassigned++;});return counts;}
async function loadIssues(){const out=$('#c-issue-list');if(!out)return;try{const data=uniqueIssues(await tryApi('/api/issues'));const summary=maintenanceSummary(data);const stats=$('#maintenance-stats');if(stats)stats.innerHTML='<div><b>'+summary.open+'</b><span>Open</span></div><div><b>'+summary.inProgress+'</b><span>In progress</span></div><div><b>'+summary.resolved+'</b><span>Awaiting verification</span></div><div><b>'+summary.critical+'</b><span>Critical</span></div>';out.replaceChildren();if(!data.length)out.innerHTML='<div class="operation-note">No maintenance issues are currently recorded.</div>';else data.forEach(i=>out.insertAdjacentHTML('beforeend',issueCard(i)));const select=$('#maintenance-issue-select');if(select)select.innerHTML='<option value="">Choose an issue to update</option>'+data.filter(i=>i.status!=='Verified').map(i=>'<option value="'+escOp(i.id)+'">'+escOp(i.rooms?.room_number||'Campus')+' · '+escOp(i.title)+' · '+escOp(i.status)+'</option>').join('');const verifySelect=$('.maintenance-verify-issue');if(verifySelect)verifySelect.innerHTML='<option value="">Choose resolved issue</option>'+data.filter(i=>i.status==='Resolved').map(i=>'<option value="'+escOp(i.id)+'">'+escOp(i.rooms?.room_number||'Campus')+' · '+escOp(i.title)+'</option>').join('');const roomSelect=$('#maintenance-room-select');if(roomSelect&&!roomSelect.dataset.loaded){const rooms=await tryApi('/api/rooms');roomSelect.innerHTML='<option value="">Choose room</option>'+(rooms||[]).map(r=>'<option value="'+escOp(r.id)+'">'+escOp(r.room_number)+' · '+escOp(r.room_name)+'</option>').join('');roomSelect.dataset.loaded='1';}}catch(err){out.replaceChildren();out.innerHTML='<div class="operation-note"><b>Maintenance queue unavailable.</b> '+escOp(err.message)+'</div>';}}function opShell(d,body){return `<div class="operation-head"><span>${d.icon}</span><div><h3>${d.title}</h3><p>${d.intro}</p></div></div>${body}`;}
function openOperation(key){const k=key||'optimizer';if(!currentProfile){openAccessDialog();return}if(!hasAccess('operations',k)){denyAccess();return}const d=operation[k];$$('.operation-nav-grid button').forEach(b=>b.classList.toggle('active',b.dataset.operation===k));let body='';
if(k==='optimizer')body=`<form class="operation-form" data-op-form="optimizer"><label>Students<input name="students" type="number" min="1" required value="${localOps.optimizer?.students||30}"></label><label>Day<select name="day"><option>Monday</option><option>Tuesday</option><option>Wednesday</option><option>Thursday</option><option>Friday</option><option>Saturday</option></select></label><label>Start time<input name="start_time" type="time" required value="${localOps.optimizer?.start_time||'09:00'}"></label><label>End time<input name="end_time" type="time" required value="${localOps.optimizer?.end_time||'10:00'}"></label><label>Projector<select name="projector"><option value="">Not required</option><option value="true">Required</option></select></label><label>Network<select name="network"><option value="">Not required</option><option value="true">Required</option></select></label><label>Board<select name="board"><option value="">Not required</option><option value="true">Required</option></select></label><button class="primary azure" type="submit">✦ Find best-fit rooms</button></form><div id="optimizer-result" class="operation-note">Enter the class requirements and run the optimizer.</div><button type="button" class="ai-inline-button" data-ai-explain="optimizer">✦ Hybrid AI explanation</button><div id="optimizer-ai-panel" class="inline-ai-panel" hidden></div>`;
if(k==='rooms')body=`<div class="rooms-toolbar"><div class="room-search"><span>⌕</span><input id="c-room-search" placeholder="Search room number or name"></div><div class="room-filters"><button class="selected" data-room-filter="All">All</button><button data-room-filter="Classroom">Classroom</button><button data-room-filter="Laboratory">Laboratory</button><button data-room-filter="Faculty Room">Faculty Room</button><button data-room-filter="HOD Room">HOD Room</button><button data-room-filter="Seminar Hall">Seminar Hall</button><button data-room-filter="Toilet">Toilet</button><button data-room-filter="Other">Other</button></div><button type="button" data-add-room class="room-add">＋ Add room</button></div><div class="room-summary"><span><b id="c-room-total">12</b> Rooms</span><span><b id="c-room-available">8</b> Available</span><span><b id="c-room-attention">2</b> Attention</span><span><b id="c-room-unavailable">1</b> Unavailable</span><span><b id="c-room-empty">1</b> Empty</span><span><b id="c-room-seats">585</b> Seats</span></div><div id="c-room-grid" class="room-grid-list"></div><div class="operation-actions"><button type="button" data-load-rooms>↻ Refresh live room data</button></div>`;
if(k==='maintenance')body='<div class="maintenance-summary" id="maintenance-stats"><div><b>—</b><span>Open</span></div><div><b>—</b><span>In progress</span></div><div><b>—</b><span>Awaiting verification</span></div><div><b>—</b><span>Critical</span></div></div><div class="issue-toolbar"><div><b>Maintenance queue</b><span>Report → assign → repair → verify. Every status is stored in the live database.</span></div><button type="button" data-refresh-issues>↻ Refresh</button></div><div id="c-issue-list" class="issue-list-dashboard"></div><div class="maintenance-workspace"><form class="operation-form maintenance-report-form" data-maintenance-report><h4>Report an issue</h4><label>Room<select id="maintenance-room-select" name="room_id" required><option value="">Loading rooms…</option></select></label><label>Issue title<input name="title" required maxlength="120" placeholder="Projector has no display"></label><label>Category<select name="category" required><option value="">Choose category</option><option>Equipment</option><option>Network</option><option>Electrical</option><option>Plumbing</option><option>Safety</option><option>Other</option></select></label><label>Priority<select name="priority" required><option>Low</option><option>Medium</option><option>High</option><option>Critical</option></select></label><label class="full">Description<textarea name="description" required minlength="8" placeholder="Describe the problem, symptoms, and expected action."></textarea></label><button class="primary azure" type="submit">⚑ Report issue</button><div id="maintenance-report-result" class="operation-note">Faculty can create a new maintenance issue.</div></form><form class="operation-form maintenance-repair-form" data-op-form="maintenance"><h4>Update repair</h4><label>Issue<select name="issue_id" id="maintenance-issue-select" required><option value="">Loading issues…</option></select></label><label>Status<select name="status" required><option>In Progress</option><option>Resolved</option></select></label><label class="full">Worker note<textarea name="worker_note" maxlength="1000" placeholder="Inspection, repair performed, parts replaced, or follow-up needed."></textarea></label><button class="primary azure" type="submit">Save repair update</button><div id="maintenance-result" class="operation-note">Workers can update assigned repair work.</div></form><form class="operation-form maintenance-verify-form" data-maintenance-verify><h4>Faculty verification</h4><label>Issue<select name="issue_id" class="maintenance-verify-issue" required><option value="">Choose resolved issue</option></select></label><label>Decision<select name="verdict" required><option>Verified</option><option>Reopened</option></select></label><label class="full">Verification note<textarea name="faculty_note" maxlength="1000" placeholder="Confirm the repair or explain why it needs more work."></textarea></label><button class="primary azure" type="submit">Save verification</button><div id="maintenance-verify-result" class="operation-note">Faculty can verify resolved work or reopen it.</div></form></div>';
if(k==='timetable')body=`<div class="operation-crud-head"><div><b>Timetable records</b><span>Schedule grid matches the paper timetable layout. Edit or delete any live entry from its cell.</span></div><button type="button" data-crud-new-timetable class="room-add">＋ New entry</button></div><div class="operation-view-tabs" role="tablist" aria-label="Timetable views"><button type="button" class="selected" data-timetable-view="schedule">Schedule view</button></div><div id="timetable-result" class="operation-note">Live timetable entries are loaded from the database.</div><section id="timetable-schedule-view"><div id="timetable-schedule-table" class="schedule-grid-wrap"></div></section><section id="timetable-records-view" hidden><div id="timetable-list" class="operation-table-wrap"></div></section><div class="upload-panel"><label>Upload timetable CSV/XLSX<input id="timetable-upload" type="file" accept=".csv,.tsv,.xlsx,.xlsm"></label><button type="button" class="primary azure" data-upload="timetable">Upload and save timetable</button><small>Columns: day, start_time, end_time, room_number, section, subject_code</small></div>`;
if(k==='progress')body=`<div class="operation-crud-head"><div><b>Syllabus progress records</b><span>Live records with the same add/edit dialog workflow used by Rooms & resources.</span></div><button type="button" data-crud-new-progress class="room-add">＋ New update</button></div><div class="progress-summary"><span><b id="c-progress-subjects">0</b> Subjects tracked</span><span><b id="c-progress-average">0%</b> Avg coverage</span><span><b id="c-progress-completed">0</b> Completed</span><span><b id="c-progress-updates">0</b> Weekly updates</span></div><div id="progress-result" class="operation-note">Live syllabus coverage is stored by subject and week.</div><div id="progress-list" class="operation-table-wrap"></div><div class="upload-panel"><label>Upload syllabus progress CSV/XLSX<input id="progress-upload" type="file" accept=".csv,.tsv,.xlsx,.xlsm"></label><button type="button" class="primary azure" data-upload="progress">Upload and save progress</button><small>Columns: subject_code, week_number, coverage_percent, topics_covered</small></div>`;
if(activeDetail||!$('#connect')?.classList.contains('active'))showView('connect');if($('#operation-title'))$('#operation-title').textContent=d.title;const panel=$('#connect-operation-panel'),content=$('#connect-operation-content');if(panel&&content){content.innerHTML=opShell(d,body);panel.hidden=false;panel.classList.add('open');setTopbarTheme('connect');syncBotVisibility();setTimeout(()=>panel.scrollIntoView({behavior:'smooth',block:'start'}),20);}if(k==='rooms'){loadLiveRooms();}if(k==='maintenance'){loadIssues();}if(k==='timetable'){hydrateTimetableForm();loadTimetableList();}if(k==='progress'){hydrateProgressForm();loadProgressSummary();loadProgressList();}}
