let timetableRowsCache=[],progressRowsCache=[];async function hydrateTimetableForm(){const f=$('[data-legacy-op-form="timetable"]');if(!f)return;try{const [rooms,subjects]=await Promise.all([tryApi('/api/rooms'),tryApi('/api/subjects')]);const rSel=f.elements.room,sSel=f.elements.subject;const roomWanted=localOps.timetable?.room||'';const subjWanted=localOps.timetable?.subject||'';rSel.innerHTML='<option value="">Choose room</option>'+(rooms||[]).map(r=>`<option value="${escOp(r.room_number)}">${escOp(r.room_number)} · ${escOp(r.room_name)}</option>`).join('');sSel.innerHTML='<option value="">Choose subject</option>'+(subjects||[]).map(s=>`<option value="${escOp(s.code)}">${escOp(s.code)} · ${escOp(s.name)}</option>`).join('');rSel.value=roomWanted&&[...rSel.options].some(o=>o.value===roomWanted)?roomWanted:(rooms?.[0]?.room_number||'');sSel.value=subjWanted&&[...sSel.options].some(o=>o.value===subjWanted)?subjWanted:(subjects?.[0]?.code||'');const chosen=subjects?.find(s=>s.code===sSel.value);if(f.elements.credits&&chosen)f.elements.credits.value=chosen.credits||'';}catch(err){const out=$('#timetable-result');if(out)out.textContent='Could not load rooms/subjects: '+err.message;}}
async function hydrateProgressForm(){const f=$('[data-legacy-op-form="progress"]');if(!f)return;try{const subjects=await tryApi('/api/subjects');const sel=f.elements.code;const wanted=localOps.progress?.code||'';sel.innerHTML='<option value="">Choose subject</option>'+(subjects||[]).map(s=>`<option value="${escOp(s.code)}">${escOp(s.code)} · ${escOp(s.name)}</option>`).join('');sel.value=wanted&&[...sel.options].some(o=>o.value===wanted)?wanted:(subjects?.[0]?.code||'');const chosen=subjects?.find(s=>s.code===sel.value);if(f.elements.credits&&chosen)f.elements.credits.value=chosen.credits||'';}catch(err){const out=$('#progress-result');if(out)out.textContent='Could not load subjects: '+err.message;}}

function timetableSlotKey(row){return `${String(row?.start_time||'').slice(0,5)}-${String(row?.end_time||'').slice(0,5)}`;}
function timetableTimeSlots(rows){const seen=new Map();(rows||[]).forEach(r=>{const key=timetableSlotKey(r);if(!key||key==='-')return;if(!seen.has(key))seen.set(key,{key,start:String(r.start_time||'').slice(0,5),end:String(r.end_time||'').slice(0,5)});});return [...seen.values()].sort((a,b)=>a.start.localeCompare(b.start)).slice(0,10);}
function timetableEntriesFor(rows,day,slot){return (rows||[]).filter(r=>r.day===day&&timetableSlotKey(r)===slot.key);}
function scheduleEntryMarkup(row,showActions=true){const code=row.subjects?.code||'Subject';const teacher=row.profiles?.name||'Unassigned';const room=row.rooms?.room_number||'';const meta=[row.section,room].filter(Boolean).join(' · ');return `<div class="schedule-entry"><b>${escOp(code)}</b><small>${escOp(row.subjects?.name||'')}</small>${showActions?`<button type="button" class="schedule-edit" data-crud-edit-timetable="${escOp(row.id)}">Edit</button><button type="button" class="schedule-delete" data-crud-delete-timetable="${escOp(row.id)}">Delete</button>`:''}</div>`;}
function scheduleTeacherMarkup(row){return `<div class="schedule-teacher"><b>${escOp(row.profiles?.name||'Unassigned')}</b><small>${escOp([row.section,row.rooms?.room_number].filter(Boolean).join(' · '))}</small></div>`;}
function renderTimetableSchedule(rows){const host=$('#timetable-schedule-table');if(!host)return;const days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];const slots=timetableTimeSlots(rows||[]);if(!slots.length){host.innerHTML='<div class="operation-note">No timetable entries saved yet. Add an entry to build the schedule grid.</div>';return;}const head=`<th class="schedule-corner"><span>DAY</span><small>SUBJECT / TEACHER</small></th>${slots.map((s,i)=>`<th><span>PERIOD ${i+1}</span><small>${escOp(s.start)} – ${escOp(s.end)}</small></th>`).join('')}`;const rowsHtml=days.map(day=>{const subjectCells=slots.map(slot=>{const entries=timetableEntriesFor(rows,day,slot);return `<td>${entries.length?entries.map(r=>scheduleEntryMarkup(r,true)).join(''): '<span class="schedule-empty">—</span>'}</td>`;}).join('');const teacherCells=slots.map(slot=>{const entries=timetableEntriesFor(rows,day,slot);return `<td>${entries.length?entries.map(scheduleTeacherMarkup).join(''):'<span class="schedule-empty">—</span>'}</td>`;}).join('');return `<tr class="schedule-subject-row"><th class="schedule-day" scope="row"><b>${escOp(day)}</b><span>SUBJECT</span></th>${subjectCells}</tr><tr class="schedule-teacher-row"><th class="schedule-day secondary" scope="row"><b>${escOp(day)}</b><span>TEACHER</span></th>${teacherCells}</tr>`;}).join('');host.innerHTML=`<div class="schedule-grid-scroller"><table class="schedule-grid"><thead><tr>${head}</tr></thead><tbody>${rowsHtml}</tbody></table></div>`;}
async function loadTimetableList(){const host=$('#timetable-list');if(!host)return;try{const rows=await tryApi('/api/timetable');timetableRowsCache=Array.isArray(rows)?rows:[];renderTimetableSchedule(timetableRowsCache);host.innerHTML=timetableRowsCache.length?`<table class="operation-table crud-table"><thead><tr><th>Day</th><th>Time</th><th>Room</th><th>Section</th><th>Subject</th><th>Teacher</th><th>Actions</th></tr></thead><tbody>${timetableRowsCache.map(r=>`<tr><td>${escOp(r.day)}</td><td>${escOp(String(r.start_time).slice(0,5))}–${escOp(String(r.end_time).slice(0,5))}</td><td>${escOp(r.rooms?.room_number||'')}</td><td>${escOp(r.section)}</td><td><b>${escOp(r.subjects?.code||'')}</b><small>${escOp(r.subjects?.name||'')}</small></td><td>${escOp(r.profiles?.name||'Unassigned')}</td><td class="crud-actions"><button type="button" data-crud-edit-timetable="${escOp(r.id)}">Edit</button><button type="button" data-crud-delete-timetable="${escOp(r.id)}" class="danger-action">Delete</button></td></tr>`).join('')}</tbody></table>`:'<div class="operation-note">No timetable entries saved yet.</div>';}catch(err){if(host)host.innerHTML=`<div class="operation-note">Could not load timetable: ${escOp(err.message)}</div>`;const schedule=$('#timetable-schedule-table');if(schedule)schedule.innerHTML='<div class="operation-note">Could not load the schedule grid.</div>';}}
async function loadProgressList(){const host=$('#progress-list');if(!host)return;try{const rows=await tryApi('/api/progress');progressRowsCache=rows||[];host.innerHTML=progressRowsCache.length?`<table class="operation-table crud-table"><thead><tr><th>Subject</th><th>Week</th><th>Coverage</th><th>Topics covered</th><th>Updated</th><th>Actions</th></tr></thead><tbody>${progressRowsCache.map(r=>`<tr><td><b>${escOp(r.subjects?.code||'')}</b><small>${escOp(r.subjects?.name||'')}</small></td><td>${escOp(r.week_number)}</td><td>${escOp(r.coverage_percent)}%</td><td>${escOp(r.topics_covered)}</td><td>${escOp(r.updated_at?new Date(r.updated_at).toLocaleString():'')}</td><td class="crud-actions"><button type="button" data-crud-edit-progress="${escOp(r.id)}">Edit</button><button type="button" data-crud-delete-progress="${escOp(r.id)}" class="danger-action">Delete</button></td></tr>`).join('')}</tbody></table>`:'<div class="operation-note">No syllabus progress saved yet.</div>';}catch(err){host.innerHTML=`<div class="operation-note">Could not load syllabus progress: ${escOp(err.message)}</div>`;}}
async function uploadOperationFile(kind){const input=kind==='timetable'?$('#timetable-upload'):$('#progress-upload');if(!input?.files?.[0]){toast('Choose a file first.');return;}const form=new FormData();form.append('file',input.files[0]);const out=$(`#${kind}-result`);try{const r=await fetch(`/api/${kind==='timetable'?'timetable':'progress'}/upload`,{method:'POST',body:form});const data=await r.json().catch(()=>({}));if(!r.ok)throw Error([data.error,...(data.details||[])].filter(Boolean).join(' '));out.innerHTML=`<b>Upload saved.</b> ${escOp(data.inserted??data.upserted??0)} records saved${data.skipped?` · ${escOp(data.skipped)} duplicates skipped`:''}.`;input.value='';if(kind==='timetable'){await loadTimetableList();}else{await loadProgressList();await loadProgressSummary();}toast(`${kind==='timetable'?'Timetable':'Syllabus progress'} uploaded successfully.`);}catch(err){out.innerHTML=`<b>Upload failed.</b> ${escOp(err.message)}`;}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-upload]');if(b)uploadOperationFile(b.dataset.upload);});
document.addEventListener('click',async e=>{
 const editTime=e.target.closest('[data-legacy-edit-timetable]');
 const deleteTime=e.target.closest('[data-legacy-delete-timetable]');
 const editProgress=e.target.closest('[data-legacy-edit-progress]');
 const deleteProgress=e.target.closest('[data-legacy-delete-progress]');
 const newTime=e.target.closest('[data-legacy-timetable-new]');
 const newProgress=e.target.closest('[data-legacy-progress-new]');
 try {
  if(newTime){
   const f=$('[data-op-form="timetable"]');
   if(f){f.reset();f.elements.editing_id.value='';f.querySelector('[data-timetable-submit]').textContent='◫ Save clash-free entry';await hydrateTimetableForm();}
   return;
  }
  if(newProgress){
   const f=$('[data-op-form="progress"]');
   if(f){f.reset();f.elements.editing_id.value='';f.querySelector('[data-progress-submit]').textContent='📈 Save syllabus update';await hydrateProgressForm();}
   return;
  }
  if(editTime){
   const row=timetableRowsCache.find(r=>String(r.id)===String(editTime.dataset.editTimetable));
   const f=$('[data-op-form="timetable"]');
   if(!row||!f) return;
   await hydrateTimetableForm();
   f.elements.editing_id.value=row.id;
   f.elements.day.value=row.day;
   f.elements.start_time.value=String(row.start_time||'').slice(0,5);
   f.elements.end_time.value=String(row.end_time||'').slice(0,5);
   f.elements.section.value=row.section||'';
   f.elements.room.value=row.rooms?.room_number||'';
   f.elements.subject.value=row.subjects?.code||'';
   f.querySelector('[data-timetable-submit]').textContent='◫ Update clash-free entry';
   $('#timetable-result').textContent='Editing the selected timetable row. Changes are re-checked for clashes.';
   f.scrollIntoView({behavior:'smooth',block:'center'});
   return;
  }
  if(editProgress){
   const row=progressRowsCache.find(r=>String(r.id)===String(editProgress.dataset.editProgress));
   const f=$('[data-op-form="progress"]');
   if(!row||!f) return;
   await hydrateProgressForm();
   f.elements.editing_id.value=row.id;
   f.elements.code.value=row.subjects?.code||'';
   f.elements.week_number.value=row.week_number;
   f.elements.coverage_percent.value=row.coverage_percent;
   f.elements.topics_covered.value=row.topics_covered||'';
   if(f.elements.credits) f.elements.credits.value=row.subjects?.credits||'';
   f.querySelector('[data-progress-submit]').textContent='📈 Update syllabus entry';
   $('#progress-result').textContent='Editing the selected syllabus progress row. Subject/week duplicates are prevented.';
   f.scrollIntoView({behavior:'smooth',block:'center'});
   return;
  }
  if(deleteTime){
   const id=deleteTime.dataset.deleteTimetable;
   if(!confirm('Delete this timetable entry?')) return;
   await tryApi(`/api/timetable/${encodeURIComponent(id)}`,{method:'DELETE'});
   await loadTimetableList();
   $('#timetable-result').textContent='Timetable entry deleted.';
   return;
  }
  if(deleteProgress){
   const id=deleteProgress.dataset.deleteProgress;
   if(!confirm('Delete this syllabus progress entry?')) return;
   await tryApi(`/api/progress/${encodeURIComponent(id)}`,{method:'DELETE'});
   await loadProgressList();
   await loadProgressSummary();
   $('#progress-result').textContent='Syllabus progress entry deleted.';
  }
 } catch(err) {
  const out=$('#'+(editTime||deleteTime?'timetable-result':'progress-result'));
  if(out) out.innerHTML=`<b>Action failed.</b> ${escOp(err.message)}`;
 }
});

document.addEventListener('submit',async e=>{const form=e.target.closest('[data-op-form]');if(!form)return;e.preventDefault();const key=form.dataset.op,data=Object.fromEntries(new FormData(form));saveLocalOp(key,data);const out=$(`#${key}-result`);const submit=form.querySelector('button[type="submit"]');if(submit){submit.disabled=true;submit.dataset.originalText=submit.textContent;submit.textContent='Saving…';}try{if(key==='optimizer'){const payload={...data,students:Number(data.students),projector:data.projector==='true',network:data.network==='true',board:data.board==='true'};const d=await tryApi('/api/optimizer',{method:'POST',body:JSON.stringify(payload)});window.lastOptimizerResult=d;out.innerHTML=d.recommendations?.length?`<b>${escOp(d.analysis)}</b><ul>${d.recommendations.map(r=>`<li><b>${escOp(r.room_number)} · ${escOp(r.room_name)}</b> — score ${escOp(r.score)}. ${r.reasons.map(escOp).join(' · ')}</li>`).join('')}</ul>`:'No matching rooms found.';}else if(key==='maintenance'){if(!data.issue_id)throw Error('Choose an existing issue.');const status=data.status==='Open'?'In Progress':data.status;await tryApi(`/api/issues/${encodeURIComponent(data.issue_id)}/repair`,{method:'PATCH',body:JSON.stringify({status,worker_note:data.worker_note||''})});out.textContent='Live maintenance update saved.';loadIssues();}else if(key==='timetable'){const [rooms,subjects]=await Promise.all([tryApi('/api/rooms'),tryApi('/api/subjects')]);const room=rooms.find(r=>String(r.room_number).trim().toLowerCase()===data.room.trim().toLowerCase());const subject=subjects.find(s=>String(s.code).trim().toLowerCase()===data.subject.trim().toLowerCase());if(!room)throw Error('Room not found in the live database.');if(!subject)throw Error('Subject code not found in the live database.');const dayOrder={Monday:1,Tuesday:2,Wednesday:3,Thursday:4,Friday:5,Saturday:6};const payload={day:data.day,day_order:dayOrder[data.day],start_time:data.start_time,end_time:data.end_time,room_id:room.id,section:data.section,subject_id:subject.id};if(data.editing_id){await tryApi(`/api/timetable/${encodeURIComponent(data.editing_id)}`,{method:'PATCH',body:JSON.stringify(payload)});out.innerHTML='<b>Updated.</b> Timetable row saved to the live database.';}else{await tryApi('/api/timetable',{method:'POST',body:JSON.stringify(payload)});out.innerHTML='<b>Created.</b> Timetable row saved to the live database.';}form.elements.editing_id.value='';form.querySelector('[data-timetable-submit]').textContent='◫ Save clash-free entry';await loadTimetableList();}else if(key==='progress'){const subjects=await tryApi('/api/subjects');const subject=subjects.find(s=>String(s.code).trim().toLowerCase()===data.code.trim().toLowerCase());if(!subject)throw Error('Subject code not found in the live database.');const payload={subject_id:subject.id,week_number:Number(data.week_number),coverage_percent:Number(data.coverage_percent),topics_covered:data.topics_covered};if(data.editing_id){await tryApi(`/api/progress/${encodeURIComponent(data.editing_id)}`,{method:'PATCH',body:JSON.stringify(payload)});out.innerHTML='<b>Updated.</b> Syllabus progress row saved to the live database.';}else{await tryApi('/api/progress',{method:'POST',body:JSON.stringify(payload)});out.innerHTML='<b>Created.</b> Syllabus progress row saved to the live database.';}form.elements.editing_id.value='';form.querySelector('[data-progress-submit]').textContent='📈 Save syllabus update';await loadProgressList();await loadProgressSummary();}}catch(err){out.innerHTML=`<b>Live save failed.</b> ${escOp(err.message)}`;}finally{if(submit){submit.disabled=false;submit.textContent=submit.dataset.originalText||'Save';}}});

document.addEventListener('click',async e=>{if(e.target.closest('[data-room-filter]')){const b=e.target.closest('[data-room-filter]');activeRoomCategory=b.dataset.roomFilter;$$('[data-room-filter]').forEach(x=>x.classList.toggle('selected',x===b));renderRooms();}if(e.target.closest('[data-room]')&&$('#c-room-grid')){const key=e.target.closest('[data-room]').dataset.room;const r=roomDirectory.find(v=>v.room_number===key)||roomDirectory.find(v=>v.room_name===key);if(r)showRoomDetail(r);}if(e.target.closest('[data-add-room]')){openRoomDialog();}if(e.target.closest('[data-edit-room]')){const key=e.target.closest('[data-edit-room]').dataset.editRoom;const r=roomDirectory.find(v=>v.room_number===key);if(r)openRoomDialog(r);}if(e.target.closest('[data-load-rooms]')){loadLiveRooms();}if(e.target.closest('[data-refresh-issues]'))loadIssues();});
$('#room-add-dialog')?.addEventListener('click',e=>{if(e.target.id==='room-add-dialog')e.target.close();});
$('.room-dialog-close')?.addEventListener('click',()=>$('#room-add-dialog')?.close());
$('.room-dialog-cancel')?.addEventListener('click',()=>$('#room-add-dialog')?.close());
function openRoomDialog(room=null){const form=$('#room-add-form'),dialog=$('#room-add-dialog');if(!form||!dialog)return;form.reset();form.querySelector('[name=editing_room_number]').value=room?.room_number||'';$('#room-dialog-title').textContent=room?'Edit room':'Add a room';const values={room_number:room?.room_number||'',room_name:room?.room_name||'',category:room?.category||'Classroom',floor:room?.floor||'Ground Floor',capacity:room?.capacity??30,occupied_seats:room?.occupied_seats??0,benches:room?.benches??15,projector:room?.projector||'Available',board:room?.board||'Smart Board',network:room?.internet||room?.network||'Available',status:room?.status||'Available',resources:room?.other_resources||room?.resources||''};Object.entries(values).forEach(([k,v])=>{const el=form.elements[k];if(el)el.value=v;});$('#room-dialog-submit').textContent=room?'Save changes':'＋ Add room';dialog.showModal();}
$('#room-add-form')?.addEventListener('submit',async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));const editing=data.editing_room_number;delete data.editing_room_number;data.capacity=Number(data.capacity||0);data.occupied_seats=Number(data.occupied_seats||0);data.benches=Number(data.benches||0);const payload={room_number:data.room_number,room_name:data.room_name,category:data.category,floor:data.floor,capacity:data.capacity,benches:data.benches,occupied_seats:data.occupied_seats,projector:data.projector,board:data.board,internet:data.network,other_resources:data.resources||'',status:data.status};try{const session=await tryApi('/api/session');if(!session?.profile?.id||session.profile.role!=='faculty')throw Error('Sign in as faculty before saving a room.');let saved;if(editing){const existing=roomDirectory.find(r=>r.room_number===editing);if(!existing?.id)throw Error('The selected room is not loaded from the live database. Refresh live room data first.');saved=await tryApi(`/api/rooms/${existing.id}`,{method:'PATCH',body:JSON.stringify(payload)});}else{saved=await tryApi('/api/rooms',{method:'POST',body:JSON.stringify(payload)});}e.target.reset();$('#room-add-dialog')?.close();toast(`${saved.room_number} · ${editing?'updated':'added'} successfully.`);await loadLiveRooms();loadConnectMapRooms();loadConnectDashboard();}catch(err){toast(err.message||'Room could not be saved.');}});
function showRoomDetail(r){const detail=$('#c-room-detail');if(detail){detail.innerHTML=`<b>${escOp(r.room_number)} · ${escOp(r.room_name)}</b><p>${escOp(r.category)} · capacity ${escOp(r.capacity)} · occupied ${escOp(r.occupied_seats)} · status ${escOp(r.status)}.</p><p>Equipment: ${escOp(r.projector)}, ${escOp(r.board)}, ${escOp(r.internet||r.network)}. Recommended next action: ${r.status==='Attention'?'Open a maintenance check.':r.status==='Unavailable'?'Keep out of booking until cleared.':'Use this room for the next compatible allocation.'}</p>`;detail.scrollIntoView({behavior:'smooth',block:'center'});}else toast(`${r.room_name} — ${r.status}`);}

async function openCrudDialog(id,mode,row=null){
 const dialog=$('#'+id); if(!dialog)return;
 const form=dialog.querySelector('form'); if(!form)return;
 form.reset();
 if(mode==='timetable'){
   await loadLiveRooms();
   const rooms=roomDirectory||[];
   const roomSel=form.elements.room, subjectSel=form.elements.subject;
   roomSel.innerHTML='<option value="">Choose room</option>'+rooms.map(r=>'<option value="'+escOp(r.room_number)+'">'+escOp(r.room_number)+' · '+escOp(r.room_name)+'</option>').join('');
   tryApi('/api/subjects').then(subjects=>{
     subjectSel.innerHTML='<option value="">Choose subject</option>'+(subjects||[]).map(s=>'<option value="'+escOp(s.code)+'">'+escOp(s.code)+' · '+escOp(s.name)+'</option>').join('');
     if(row){form.elements.subject.value=row.subjects?.code||'';}
   }).catch(err=>{const out=$('#timetable-result');if(out)out.textContent='Could not load subjects: '+err.message;});
   form.elements.editing_id.value=row?.id||'';
   form.elements.day.value=row?.day||'Monday';
   form.elements.section.value=row?.section||'CSE-A';
   form.elements.start_time.value=String(row?.start_time||'16:00').slice(0,5);
   form.elements.end_time.value=String(row?.end_time||'16:50').slice(0,5);
   form.elements.room.value=row?.rooms?.room_number||'';
   $('#timetable-dialog-title').textContent=row?'Edit timetable entry':'Add timetable entry';
   $('#timetable-dialog-submit').textContent=row?'Save changes':'＋ Add entry';
 }else{
   const sel=form.elements.code;
   tryApi('/api/subjects').then(subjects=>{
     sel.innerHTML='<option value="">Choose subject</option>'+(subjects||[]).map(s=>'<option value="'+escOp(s.code)+'">'+escOp(s.code)+' · '+escOp(s.name)+'</option>').join('');
     if(row){sel.value=row.subjects?.code||'';if(form.elements.credits)form.elements.credits.value=row.subjects?.credits||'';}
   }).catch(err=>{const out=$('#progress-result');if(out)out.textContent='Could not load subjects: '+err.message;});
   form.elements.editing_id.value=row?.id||'';
   form.elements.week_number.value=row?.week_number||8;
   form.elements.coverage_percent.value=row?.coverage_percent??72;
   form.elements.topics_covered.value=row?.topics_covered||'';
   if(form.elements.credits)form.elements.credits.value=row?.subjects?.credits||4;
   $('#progress-dialog-title').textContent=row?'Edit syllabus update':'Add syllabus update';
   $('#progress-dialog-submit').textContent=row?'Save changes':'＋ Add update';
 }
 dialog.showModal();
}
async function saveCrudDialog(form,kind){
 const data=Object.fromEntries(new FormData(form));
 const button=form.querySelector('button[type="submit"]');
 if(button){button.disabled=true;button.textContent='Saving…';}
 try{
   const session=await tryApi('/api/session');
   if(!session?.profile?.id||session.profile.role!=='faculty')throw Error('Sign in as faculty before saving.');
   if(kind==='timetable'){
     const rooms=await tryApi('/api/rooms'),subjects=await tryApi('/api/subjects');
     const room=rooms.find(r=>String(r.room_number).trim().toLowerCase()===String(data.room).trim().toLowerCase());
     const subject=subjects.find(s=>String(s.code).trim().toLowerCase()===String(data.subject).trim().toLowerCase());
     if(!room)throw Error('Room not found in the live database.');
     if(!subject)throw Error('Subject not found in the live database.');
     const dayOrder={Monday:1,Tuesday:2,Wednesday:3,Thursday:4,Friday:5,Saturday:6};
     const payload={day:data.day,day_order:dayOrder[data.day],start_time:data.start_time,end_time:data.end_time,room_id:room.id,section:data.section,subject_id:subject.id};
     const url=data.editing_id?'/api/timetable/'+encodeURIComponent(data.editing_id):'/api/timetable';
     const saved=await tryApi(url,{method:data.editing_id?'PATCH':'POST',body:JSON.stringify(payload)});
     $('#timetable-dialog')?.close(); toast('Timetable entry '+(data.editing_id?'updated':'added')+' successfully.'); 
     await loadTimetableList(); return saved;
   }else{
     const subjects=await tryApi('/api/subjects');
     const subject=subjects.find(s=>String(s.code).trim().toLowerCase()===String(data.code).trim().toLowerCase());
     if(!subject)throw Error('Subject not found in the live database.');
     const payload={subject_id:subject.id,week_number:Number(data.week_number),coverage_percent:Number(data.coverage_percent),topics_covered:String(data.topics_covered||'').trim()};
     const url=data.editing_id?'/api/progress/'+encodeURIComponent(data.editing_id):'/api/progress';
     const saved=await tryApi(url,{method:data.editing_id?'PATCH':'POST',body:JSON.stringify(payload)});
     $('#progress-dialog')?.close(); toast('Syllabus update '+(data.editing_id?'updated':'added')+' successfully.');
     await loadProgressList(); await loadProgressSummary(); return saved;
   }
 }catch(err){
   toast(err.message||'Could not save the record.');
   throw err;
 }finally{if(button){button.disabled=false;}}
}
document.addEventListener('click',async e=>{
 const tNew=e.target.closest('[data-crud-new-timetable]');
 const tEdit=e.target.closest('[data-crud-edit-timetable]');
 const tDel=e.target.closest('[data-crud-delete-timetable]');
 const pNew=e.target.closest('[data-crud-new-progress]');
 const pEdit=e.target.closest('[data-crud-edit-progress]');
 const pDel=e.target.closest('[data-crud-delete-progress]');
 try{
  if(tNew){openCrudDialog('timetable-dialog','timetable');return;}
  if(tEdit){const row=timetableRowsCache.find(r=>String(r.id)===String(tEdit.dataset.crudEditTimetable));if(row)openCrudDialog('timetable-dialog','timetable',row);return;}
  if(tDel){if(!confirm('Delete this timetable entry?'))return;await tryApi('/api/timetable/'+encodeURIComponent(tDel.dataset.crudDeleteTimetable),{method:'DELETE'});toast('Timetable entry deleted successfully.');await loadTimetableList();return;}
  if(pNew){openCrudDialog('progress-dialog','progress');return;}
  if(pEdit){const row=progressRowsCache.find(r=>String(r.id)===String(pEdit.dataset.crudEditProgress));if(row)openCrudDialog('progress-dialog','progress',row);return;}
  if(pDel){if(!confirm('Delete this syllabus progress entry?'))return;await tryApi('/api/progress/'+encodeURIComponent(pDel.dataset.crudDeleteProgress),{method:'DELETE'});toast('Syllabus update deleted successfully.');await loadProgressList();await loadProgressSummary();return;}
 }catch(err){const out=$('#'+(tDel||tEdit?'timetable':'progress')+'-result');if(out)out.textContent='Action failed: '+err.message;}
});
$('#timetable-dialog')?.addEventListener('click',e=>{if(e.target.id==='timetable-dialog')e.target.close();});
$('#progress-dialog')?.addEventListener('click',e=>{if(e.target.id==='progress-dialog')e.target.close();});
