let leaking=false;function bindSimulate(){const button=$('#simulate');if(!button)return;button.onclick=()=>{leaking=!leaking;$('#water-value').textContent=leaking?'20,520 L':'18,420 L';button.textContent=leaking?'Leak detected · reset simulation':'Simulate Hostel A leak ✦';$('#metric-detail h3').textContent=leaking?'Critical anomaly: Hostel A leak suspected.':'Today’s water use is efficient.';$('#metric-detail p').textContent=leaking?'Hostel A now exceeds its overnight baseline by 81%. Create a high-priority plumbing inspection ticket immediately.':'18,420 L used, 2,100 L below the projected baseline. One high-priority Hostel A anomaly still needs attention.';toast(leaking?'Critical alert created: Hostel A water anomaly.':'Leak simulation reset.');};}bindSimulate();
