const cMapDirectory={};
async function loadConnectMapRooms(){try{const rows=await tryApi('/api/rooms');const select=$('#c-room-select');const map=$('.c-big-map');const hero=$('.connect-map-card .flow-map');if(!select||!map)return;select.innerHTML='<option value="">Select a room…</option>';map.innerHTML='';if(hero)hero.querySelectorAll('.building').forEach(x=>x.remove());const eligibleRows=rows.filter(r=>Number(r.capacity)>0);const preferred=['CSE-105','CSE-107','CSE-108','CSE-109'];const heroRows=[...preferred.map(id=>eligibleRows.find(r=>r.room_number===id)).filter(Boolean),...eligibleRows.filter(r=>!preferred.includes(r.room_number))].slice(0,8);heroRows.forEach((r,mapIndex)=>{const status=r.status==='Unavailable'?'Critical':r.status==='Attention'?'Watch':'Stable';const cls=status.toLowerCase();const label=r.room_name||r.room_number;cMapDirectory[r.room_number]={name:r.room_number+' · '+label,category:r.category,capacity:r.capacity,occupied:r.occupied_seats,status,equipment:[r.projector,r.board,r.internet].filter(Boolean).join(', '),action:r.status==='Attention'?'Open a maintenance check.':r.status==='Unavailable'?'Keep out of booking until cleared.':'Suitable for compatible teaching use.'};const o=document.createElement('option');o.value=r.room_number;o.textContent=r.room_number+' · '+label;select.appendChild(o);const makeButton=(extra='building',index=mapIndex)=>{const b=document.createElement('button');b.dataset.room=r.room_number;b.dataset.mapIndex=String(index+1);b.className=extra+' '+cls;b.innerHTML=`${escOp(r.room_number)}<small>${escOp(r.capacity)} seats · ${escOp(String(r.status).toLowerCase())}</small>`;b.addEventListener('click',()=>{if(select)select.value=r.room_number;showConnectMapRoom(r.room_number);if(b.closest('.connect-map-card')){showDetail('c-map');setTimeout(()=>{const s=$('#c-room-select');if(s){s.value=r.room_number;showConnectMapRoom(r.room_number);}},80);}});return b;};map.appendChild(makeButton('building',mapIndex));if(hero&&hero.querySelector('svg')&&mapIndex<4)hero.insertBefore(makeButton('building',mapIndex),hero.querySelector('svg'));});const available=rows.filter(r=>r.status==='Available').length,attention=rows.filter(r=>r.status==='Attention').length,unavailable=rows.filter(r=>r.status==='Unavailable').length;const a=$('#c-live-available'),at=$('#c-live-attention'),u=$('#c-live-unavailable');if(a)a.textContent=available;if(at)at.textContent=attention;if(u)u.textContent=unavailable;}catch(_){}}
function showConnectMapRoom(name){const r=cMapDirectory[name],out=$('#c-room-detail');if(!r||!out)return;const cls=r.status==='Critical'?'critical':r.status==='Watch'?'watch':'stable';out.innerHTML=`<div class="room-detail-head"><div><span class="room-detail-kicker">${escOp(r.category)}</span><b>${escOp(r.name)}</b></div><span class="room-detail-status ${cls}">${escOp(r.status)}</span></div><div class="room-detail-grid"><span>Capacity<strong>${escOp(r.capacity)}</strong></span><span>Occupied<strong>${escOp(r.occupied)}</strong></span><span>Equipment<strong>${escOp(r.equipment)}</strong></span></div><p>Recommended next action: ${escOp(r.action)}</p>`;$$('.c-big-map [data-room]').forEach(b=>b.classList.toggle('selected',b.dataset.room===name));}
loadConnectMapRooms();
